import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Edit, Trash2, Plus } from 'lucide-react';

export default function MenuManagement() {
  const navigate = useNavigate();
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [products, setProducts] = useState([
    {
      id: 1,
      name: 'Hamburguesa Clásica',
      description: 'Jugosa hamburguesa de carne de res con lechuga, tomate, cebolla y queso',
      category: 'Hamburguesas',
      price: '$8.99',
      image: '🍔'
    },
    {
      id: 2,
      name: 'Frappe de Chocolate',
      description: 'Delicioso frappe de chocolate con crema batida y jarabe',
      category: 'Frappes',
      price: '$5.99',
      image: '🥤'
    },
    {
      id: 3,
      name: 'Pizza Pepperoni',
      description: 'Pizza familiar con abundante pepperoni y queso mozzarella',
      category: 'Pizzas',
      price: '$12.99',
      image: '🍕'
    },
    {
      id: 4,
      name: 'Frappe de Vainilla',
      description: 'Frappe cremoso de vainilla francesa con crema batida',
      category: 'Frappes',
      price: '$5.49',
      image: '🥤'
    },
    {
      id: 5,
      name: 'Hot Dog Especial',
      description: 'Hot dog con salchicha premium, queso, tocino y salsas especiales',
      category: 'Hot Dogs',
      price: '$6.99',
      image: '🌭'
    },
    {
      id: 6,
      name: 'Limonada Frozen',
      description: 'Refrescante limonada frozen con hielo y menta',
      category: 'Bebidas Frías',
      price: '$4.99',
      image: '🥤'
    },
    {
      id: 7,
      name: 'Alitas BBQ',
      description: 'Orden de 10 alitas bañadas en salsa BBQ con aderezo ranch',
      category: 'Alitas',
      price: '$10.99',
      image: '🍗'
    }
  ]);

  const handleDelete = (id) => {
    if (window.confirm('¿Eliminar este producto?')) {
      setProducts(products.filter(p => p.id !== id));
    }
  };

  const handleLogout = () => {
    navigate('/login');
  };

  const toggleSidebar = () => {
    setSidebarOpen(!sidebarOpen);
  };

  return (
    <div style={{ display: 'flex', height: '100vh', backgroundColor: '#F3F4F6', fontFamily: 'system-ui, -apple-system, sans-serif' }}>
      {/* Sidebar */}
      <div style={{
        width: sidebarOpen ? '227px' : '80px',
        backgroundColor: '#0F172A',
        color: 'white',
        transition: 'all 0.3s ease',
        display: 'flex',
        flexDirection: 'column',
        borderRight: '1px solid #1E293B'
      }}>
        {/* Logo */}
        <div style={{
          padding: '24px',
          borderBottom: '1px solid #334155'
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
            <div style={{
              width: '40px',
              height: '40px',
              backgroundColor: '#FF6B35',
              borderRadius: '8px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '24px',
              fontWeight: 'bold'
            }}>
              🐷
            </div>
            {sidebarOpen && (
              <div>
                <div style={{ fontWeight: 'bold', fontSize: '16px', color: 'white' }}>Cochiloco</div>
                <div style={{ fontSize: '11px', color: '#9CA3AF' }}>Panel de Administración</div>
              </div>
            )}
          </div>
        </div>

        {/* User Profile */}
        <div style={{
          padding: '16px 24px',
          borderBottom: '1px solid #334155'
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
            <div style={{
              width: '40px',
              height: '40px',
              backgroundColor: '#FF6B35',
              borderRadius: '50%',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '20px'
            }}>
              👤
            </div>
            {sidebarOpen && (
              <div>
                <div style={{ fontWeight: '600', fontSize: '14px', color: 'white' }}>Admin User</div>
                <div style={{ fontSize: '12px', color: '#9CA3AF' }}>Administrador</div>
              </div>
            )}
          </div>
        </div>

        {/* Navigation */}
        <nav style={{
          flex: 1,
          padding: '24px 12px',
          display: 'flex',
          flexDirection: 'column',
          gap: '8px'
        }}>
          <div 
            onClick={() => navigate('/dashboard')}
            style={{
              padding: '12px',
              color: '#D1D5DB',
              borderRadius: '8px',
              display: 'flex',
              alignItems: 'center',
              gap: '12px',
              cursor: 'pointer',
              fontSize: '14px',
              transition: 'all 0.2s'
            }}
            onMouseEnter={(e) => { e.currentTarget.style.backgroundColor = '#1E293B'; }}
            onMouseLeave={(e) => { e.currentTarget.style.backgroundColor = 'transparent'; }}
          >
            <span style={{ fontSize: '18px' }}>📊</span>
            {sidebarOpen && <span>Dashboard</span>}
          </div>

          <div 
            onClick={() => navigate('/menu')}
            style={{
              padding: '12px',
              backgroundColor: '#FF6B35',
              borderRadius: '8px',
              color: 'white',
              display: 'flex',
              alignItems: 'center',
              gap: '12px',
              cursor: 'pointer',
              fontSize: '14px'
            }}
          >
            <span style={{ fontSize: '18px' }}>≡</span>
            {sidebarOpen && <span>Menú</span>}
          </div>

          <div 
            onClick={() => navigate('/pedidos')}
            style={{
              padding: '12px',
              color: '#D1D5DB',
              borderRadius: '8px',
              display: 'flex',
              alignItems: 'center',
              gap: '12px',
              cursor: 'pointer',
              fontSize: '14px'
            }}
            onMouseEnter={(e) => { e.currentTarget.style.backgroundColor = '#1E293B'; }}
            onMouseLeave={(e) => { e.currentTarget.style.backgroundColor = 'transparent'; }}
          >
            <span style={{ fontSize: '18px' }}>✓</span>
            {sidebarOpen && <span>Pedidos</span>}
          </div>
        </nav>

        {/* Logout */}
        <div style={{
          padding: '12px',
          borderTop: '1px solid #334155'
        }}>
          <div 
            onClick={handleLogout}
            style={{
              padding: '12px',
              color: '#D1D5DB',
              borderRadius: '8px',
              display: 'flex',
              alignItems: 'center',
              gap: '12px',
              cursor: 'pointer',
              fontSize: '14px'
            }}
            onMouseEnter={(e) => { e.currentTarget.style.backgroundColor = '#1E293B'; }}
            onMouseLeave={(e) => { e.currentTarget.style.backgroundColor = 'transparent'; }}
          >
            <span style={{ fontSize: '18px' }}>🚪</span>
            {sidebarOpen && <span>Cerrar Sesión</span>}
          </div>
        </div>

        {/* Toggle Button */}
        <div style={{ padding: '16px 12px' }}>
          <button
            onClick={toggleSidebar}
            style={{
              width: '100%',
              padding: '8px',
              color: '#9CA3AF',
              backgroundColor: 'transparent',
              border: 'none',
              borderRadius: '8px',
              cursor: 'pointer',
              fontSize: '18px'
            }}
            onMouseEnter={(e) => {
              e.target.style.backgroundColor = '#1E293B';
              e.target.style.color = 'white';
            }}
            onMouseLeave={(e) => {
              e.target.style.backgroundColor = 'transparent';
              e.target.style.color = '#9CA3AF';
            }}
          >
            ☰
          </button>
        </div>
      </div>

      {/* Main Content */}
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'auto' }}>
        {/* Header */}
        <div style={{
          backgroundColor: 'white',
          borderBottom: '1px solid #E5E7EB',
          padding: '32px 32px',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'flex-start'
        }}>
          <div>
            <h1 style={{ fontSize: '32px', fontWeight: '700', color: '#111827', margin: 0 }}>Gestión de Menú</h1>
            <p style={{ color: '#6B7280', marginTop: '8px', margin: 0 }}>Administra el catálogo de comida y bebidas</p>
          </div>
          <button style={{
            backgroundColor: '#FF6B35',
            color: 'white',
            border: 'none',
            padding: '12px 24px',
            borderRadius: '8px',
            cursor: 'pointer',
            fontSize: '14px',
            fontWeight: '600',
            display: 'flex',
            alignItems: 'center',
            gap: '8px'
