            overflow: 'hidden'
          }}>
            {/* Table Header */}
            <div style={{
              display: 'grid',
              gridTemplateColumns: '80px 1fr 150px 100px 120px',
              padding: '16px 24px',
              backgroundColor: '#F9FAFB',
              borderBottom: '1px solid #E5E7EB',
              fontWeight: '600',
              fontSize: '14px',
              color: '#374151',
              gap: '16px'
            }}>
              <div>Imagen</div>
              <div>Nombre</div>
              <div>Categoría</div>
              <div>Precio</div>
              <div>Acciones</div>
            </div>

            {/* Table Rows */}
            {products.map((product, index) => (
              <div
                key={product.id}
                style={{
                  display: 'grid',
                  gridTemplateColumns: '80px 1fr 150px 100px 120px',
                  padding: '16px 24px',
                  borderBottom: index !== products.length - 1 ? '1px solid #E5E7EB' : 'none',
                  alignItems: 'center',
                  gap: '16px',
                  transition: 'background-color 0.2s'
                }}
                onMouseEnter={(e) => { e.currentTarget.style.backgroundColor = '#F9FAFB'; }}
                onMouseLeave={(e) => { e.currentTarget.style.backgroundColor = 'white'; }}
              >
                <div style={{
                  width: '60px',
                  height: '60px',
                  backgroundColor: '#E5E7EB',
                  borderRadius: '8px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  fontSize: '32px'
                }}>
                  {product.image}
                </div>

                <div>
                  <p style={{ fontSize: '14px', fontWeight: '600', color: '#111827', margin: 0 }}>{product.name}</p>
                  <p style={{ fontSize: '12px', color: '#6B7280', margin: '4px 0 0 0' }}>{product.description}</p>
                </div>

                <div style={{ fontSize: '14px', color: '#374151' }}>{product.category}</div>
                <div style={{ fontSize: '14px', fontWeight: '600', color: '#111827' }}>{product.price}</div>

                <div style={{ display: 'flex', gap: '8px' }}>
                  <button
                    style={{
                      backgroundColor: 'transparent',
                      border: 'none',
                      cursor: 'pointer',
                      padding: '4px',
                      color: '#6B7280'
                    }}
                    onMouseEnter={(e) => { e.target.style.color = '#FF6B35'; }}
                    onMouseLeave={(e) => { e.target.style.color = '#6B7280'; }}
                  >
                    <Edit size={18} />
                  </button>
                  <button
                    onClick={() => handleDelete(product.id)}
                    style={{
                      backgroundColor: 'transparent',
                      border: 'none',
                      cursor: 'pointer',
                      padding: '4px',
                      color: '#EF4444'
                    }}
                    onMouseEnter={(e) => { e.target.style.opacity = '0.8'; }}
                    onMouseLeave={(e) => { e.target.style.opacity = '1'; }}
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
